INSERT INTO public.scenario_version (id, scenario_id, version_number, status, title, target_role, career_track, summary, introduction, learning_objectives, difficulty, estimated_minutes, translations, provenance, content_hash, created_at, published_at, row_version, card_image_url, hero_image_url, company_logo_url, overview_video_url) VALUES (1, 1, 1, 'PUBLISHED', 'Software Engineering', 'Software Engineer', 'Software Engineering', 'Learn to design and build a RESTful web service as a backend developer in Hewlett Packard Enterprise''s Software Engineering job simulation on Forage', 'Software Engineering Program', '<ul><li>The basics of Java Spring Boot, HPE GreenLake and RESTful Web Services</li></ul>
INSERT INTO public.scenario_version (id, scenario_id, version_number, status, title, target_role, career_track, summary, introduction, learning_objectives, difficulty, estimated_minutes, translations, provenance, content_hash, created_at, published_at, row_version, card_image_url, hero_image_url, company_logo_url, overview_video_url) VALUES (2, 2, 1, 'PUBLISHED', 'Service Desk', 'Service Desk Analyst', 'IT Service Desk', 'Learn how to resolve technical issues and when to escalate in Datacom''s Service Desk job simulation on Forage', 'Learn how to resolve technical issues and when to escalate in Datacom''s Service Desk job simulation on Forage', '<ul><li><span style="color:#1d1c1d;">Techniques for effective problem identification and troubleshooting of basic technical issues.</span></li><li><span style="color:#1d1c1d;">Principles of excellent customer service and communication in an IT support context.</span></li><li><span style="color:#1d1c1d;">The importance of clear documentation and ticket management in resolving and tracking client issues.</span></li></ul>
INSERT INTO public.scenario_version (id, scenario_id, version_number, status, title, target_role, career_track, summary, introduction, learning_objectives, difficulty, estimated_minutes, translations, provenance, content_hash, created_at, published_at, row_version, card_image_url, hero_image_url, company_logo_url, overview_video_url) VALUES (3, 3, 1, 'PUBLISHED', 'Introduction to Cloud', 'Cloud Engineer', 'Cloud Computing', 'Learn what it''s like working in the Cloud Solutions team at Datacom in this virtual job simulation on Forage', 'Introduction to Cloud', '<ul><li>Meet your client, WCD Bank, who is making a strategic shift to migrate its data, applications, and IT infrastructure from on-premises data centres to cloud-based services</li><li>The fast-paced and dynamic nature of Datacom''s work environments</li></ul><p>&nbsp;</p>
INSERT INTO public.scenario_version (id, scenario_id, version_number, status, title, target_role, career_track, summary, introduction, learning_objectives, difficulty, estimated_minutes, translations, provenance, content_hash, created_at, published_at, row_version, card_image_url, hero_image_url, company_logo_url, overview_video_url) VALUES (4, 4, 1, 'PUBLISHED', 'Partnering with AI in the workplace', 'AI-enabled Professional', 'Artificial Intelligence', 'Learn skills in AI collaboration, prompt writing, communication, and problem solving in Datacom''s AI in the Workplace job simulation on Forage', 'Learn skills in AI collaboration, prompt writing, communication, and problem solving in Datacom''s AI in the Workplace job simulation on Forage', '<ul><li><span style="color:#1D1C1D;">The importance of writing effective prompts in AI&nbsp;</span><ul><li><i>Be specific</i></li><li><i>Provide context</i></li><li><i>Define the desired outcome</i></li><li><i>Ask follow-up questions</i></li></ul></li></ul>
INSERT INTO public.scenario_version (id, scenario_id, version_number, status, title, target_role, career_track, summary, introduction, learning_objectives, difficulty, estimated_minutes, translations, provenance, content_hash, created_at, published_at, row_version, card_image_url, hero_image_url, company_logo_url, overview_video_url) VALUES (5, 5, 1, 'PUBLISHED', 'Presales', 'Presales Consultant', 'Technology Presales', 'Learn how to research and present solutions to clients, and work with solutions architecture in the Hewlett Packard Enterprise Presales job simulation on Forage', 'Presales Virtual Experience Program', '<ul><li>How to research and understand HPE product offerings, especially those related to VMware, Kubernetes, and hyper-converged solutions</li><li>How to synthesize customer requirements into cost-effective solutions that align with HPE products</li><li>How to formulate relevant questions to gather essential customer information</li></ul>
INSERT INTO public.scenario_version (id, scenario_id, version_number, status, title, target_role, career_track, summary, introduction, learning_objectives, difficulty, estimated_minutes, translations, provenance, content_hash, created_at, published_at, row_version, card_image_url, hero_image_url, company_logo_url, overview_video_url) VALUES (6, 6, 1, 'PUBLISHED', 'Digital Sales', 'Digital Sales Representative', 'Digital Technology Sales', 'Learn skills to identify target customers and present finding sin the Hewlett Packard Enterprise Digital Sales job simulation on Forage', 'Enterprise Sales Program', '<ul><li>What HPE does&nbsp;</li><li>How to provide a high-level overview of a company</li><li>How to create a introductory presentation that engages a customer</li></ul>
INSERT INTO public.scenario_version (id, scenario_id, version_number, status, title, target_role, career_track, summary, introduction, learning_objectives, difficulty, estimated_minutes, translations, provenance, content_hash, created_at, published_at, row_version, card_image_url, hero_image_url, company_logo_url, overview_video_url) VALUES (7, 7, 1, 'PUBLISHED', 'Automation AI Accelerator: From Co-pilot to Autonomous Agent', 'Automation Engineer', 'Automation and AI', 'Learn what it''s like to work as an Automation Developer at Datacom, and gain skills for problem solving, automation, and client services in this job simulation on Forage', 'Automation', '<ul><li><span style="color:#000000;">How to effectively leverage an AI co-pilot to rapidly understand the function and structure of unfamiliar or legacy code.</span></li><li><span style="color:#000000;">The art and science of crafting effective, context-rich prompts specifically for debugging and refactoring tasks.</span></li><li><span style="color:#000000;">How to work iteratively with an AI, treating its suggestions as hypotheses to be tested and refined, rather than as infallible commands.</span></li><li><span style="color:#000000;">The critical importance of maintaining human oversight, applying critical thinking, and verifying all AI-generated code fixes before acceptance.</span></li></ul><p><br>&nbsp;</p>
INSERT INTO public.scenario_version (id, scenario_id, version_number, status, title, target_role, career_track, summary, introduction, learning_objectives, difficulty, estimated_minutes, translations, provenance, content_hash, created_at, published_at, row_version, card_image_url, hero_image_url, company_logo_url, overview_video_url) VALUES (9, 9, 1, 'PUBLISHED', 'Software Development', 'Software Developer', 'Software Development', 'Learn web application and root cause analysis skills used in the Software Development team at Datacom in this job simulation on Forage', 'Software Development', '<ul><li>How software developers at Datacom support and improve clients'' products</li></ul>
INSERT INTO public.scenario_version (id, scenario_id, version_number, status, title, target_role, career_track, summary, introduction, learning_objectives, difficulty, estimated_minutes, translations, provenance, content_hash, created_at, published_at, row_version, card_image_url, hero_image_url, company_logo_url, overview_video_url) VALUES (8, 8, 1, 'PUBLISHED', 'Cyber Security Operations', 'Cyber Security Analyst', 'Cybersecurity', 'Learn how to perform risk assessments and investigate cyber attacks in the Datacom Cybersecurity job simulation on Forage', 'Cybersecurity Program', '<ul><li><span style="color:#000000;">You will gain an understanding of how cybersecurity consultants analyse the impact of data breaches, including identifying vulnerabilities and assessing business consequences. The art and science of crafting effective, context-rich prompts specifically for debugging and refactoring tasks.</span></li></ul><p><br>&nbsp;</p>
