INSERT INTO public.scenario_version (id, scenario_id, version_number, status, title, target_role, career_track, summary, introduction, learning_objectives, difficulty, estimated_minutes, translations, provenance, content_hash, created_at, published_at, row_version, card_image_url, hero_image_url, company_logo_url, overview_video_url) VALUES (14, 7, 2, 'PUBLISHED', 'Automation AI Accelerator: From Co-pilot to Autonomous Agent', 'Automation Engineer', 'Automation and AI', 'Learn what it''s like to work as an Automation Developer at Datacom, and gain skills for problem solving, automation, and client services in this job simulation on Forage', 'Automation', '<ul><li><span style="color:#000000;">How to effectively leverage an AI co-pilot to rapidly understand the function and structure of unfamiliar or legacy code.</span></li><li><span style="color:#000000;">The art and science of crafting effective, context-rich prompts specifically for debugging and refactoring tasks.</span></li><li><span style="color:#000000;">How to work iteratively with an AI, treating its suggestions as hypotheses to be tested and refined, rather than as infallible commands.</span></li><li><span style="color:#000000;">The critical importance of maintaining human oversight, applying critical thinking, and verifying all AI-generated code fixes before acceptance.</span></li></ul><p><br>&nbsp;</p>
INSERT INTO public.scenario_version (id, scenario_id, version_number, status, title, target_role, career_track, summary, introduction, learning_objectives, difficulty, estimated_minutes, translations, provenance, content_hash, created_at, published_at, row_version, card_image_url, hero_image_url, company_logo_url, overview_video_url) VALUES (15, 8, 2, 'PUBLISHED', 'Cyber Security Operations', 'Cyber Security Analyst', 'Cybersecurity', 'Learn how to perform risk assessments and investigate cyber attacks in the Datacom Cybersecurity job simulation on Forage', 'Cybersecurity Program', '<ul><li><span style="color:#000000;">You will gain an understanding of how cybersecurity consultants analyse the impact of data breaches, including identifying vulnerabilities and assessing business consequences. The art and science of crafting effective, context-rich prompts specifically for debugging and refactoring tasks.</span></li></ul><p><br>&nbsp;</p>
INSERT INTO public.scenario_version (id, scenario_id, version_number, status, title, target_role, career_track, summary, introduction, learning_objectives, difficulty, estimated_minutes, translations, provenance, content_hash, created_at, published_at, row_version, card_image_url, hero_image_url, company_logo_url, overview_video_url) VALUES (16, 9, 2, 'PUBLISHED', 'Software Development', 'Software Developer', 'Software Development', 'Learn web application and root cause analysis skills used in the Software Development team at Datacom in this job simulation on Forage', 'Software Development', '<ul><li>How software developers at Datacom support and improve clients'' products</li></ul>
