INSERT INTO public.simulation_task (id, scenario_version_id, "position", title, workplace_context, instructions, required, translations) VALUES (19, 6, 4, 'Managing Your Time', '', '<p>Prioritize a variety of sales tasks in a knowledge check drag &amp; drop</p>', true, '{}');
INSERT INTO public.simulation_task (id, scenario_version_id, "position", title, workplace_context, instructions, required, translations) VALUES (1, 1, 1, 'Create a Proposal for a RESTful Web Service', 'Explore how to use Java Spring Boot and the GreenLake cloud platform to design a RESTful web service', '<ul><li>Meet your supervisor Stella Yun, a senior software Engineering Director at Hewlett Packard Enterprise</li><li>Explore the technical documentation for Java Spring Boot and GreenLake Cloud Platform</li><li>Write a proposal for a RESTful web service to manage a list of employees</li></ul>', true, '{}');
INSERT INTO public.simulation_task (id, scenario_version_id, "position", title, workplace_context, instructions, required, translations) VALUES (2, 1, 2, 'Build a Basic RESTful Web Service', 'Using Java Spring Boot, build a basic RESTful Web Service that can send basic server requests', '<ul><li>Build a basic web server application in Java Spring Boot that can accept and respond to HTTP requests</li></ul>', true, '{}');
INSERT INTO public.simulation_task (id, scenario_version_id, "position", title, workplace_context, instructions, required, translations) VALUES (3, 1, 3, 'Implement the Ability to Upload Data', 'Add application support for uploading JSON data', '<ul><li>Build out your application so that it supports uploading JSON data</li></ul>', true, '{}');
INSERT INTO public.simulation_task (id, scenario_version_id, "position", title, workplace_context, instructions, required, translations) VALUES (4, 1, 4, 'Create Unit Tests', 'Develop a set of unit tests to assess your application’s performance', '<ul><li>Develop and run a set of unit tests to assess your application’s performance</li></ul>', true, '{}');
INSERT INTO public.simulation_task (id, scenario_version_id, "position", title, workplace_context, instructions, required, translations) VALUES (5, 2, 1, 'Technical issue resolution', 'Help a Datacom client with their technical hurdles by resolving their email access issue with expert troubleshooting and communication', '<ul><li><span style="color:#1d1c1d;">Analyse a client''s reported issue with accessing its email account, identifying potential causes such as password problems, internet connectivity, or email server issues.</span></li><li><span style="color:#1d1c1d;">Guide the client through a series of troubleshooting steps over email or a simulated phone call, aiming to resolve the issue while maintaining a supportive and patient demeanour.</span></li><li><span style="color:#1d1c1d;">Document the issue, actions taken, and the outcome, ensuring all relevant information is captured for future reference or escalation.</span></li></ul>', true, '{}');
INSERT INTO public.simulation_task (id, scenario_version_id, "position", title, workplace_context, instructions, required, translations) VALUES (6, 2, 2, 'Customer support and escalation', 'Tackle a network outage with strategic prioritisation and clear client communication', '<ul><li>Prioritise a series of incoming support tickets based on urgency and impact.</li><li>Communicate with affected users of a network outage to provide updates and maintain customer satisfaction.<br><br>&nbsp;</li></ul>', true, '{}');
INSERT INTO public.simulation_task (id, scenario_version_id, "position", title, workplace_context, instructions, required, translations) VALUES (7, 3, 1, 'Register an application on the cloud', 'Simulate your first day at work with Datacom', '<ul><li>Enable a function for WCD Bank in the implementation phase of a new project</li></ul>', true, '{}');
INSERT INTO public.simulation_task (id, scenario_version_id, "position", title, workplace_context, instructions, required, translations) VALUES (8, 3, 2, 'Create a GitHub Action workflow', 'Experience the most used tool in the computer science world', '<ul><li>Create and clone your first repository to your local machine through a terminal and create a GitHub action with Yaml</li></ul>', true, '{}');
INSERT INTO public.simulation_task (id, scenario_version_id, "position", title, workplace_context, instructions, required, translations) VALUES (9, 4, 1, 'Writing effective prompts', 'Start smart. Learn to ask better questions and get better results with AI.', '<p>You’ll be working with a team that has been asked to develop a new feature for a client’s website. You’ll need to explore options, plan, and communicate with the wider Datacom team.</p>', true, '{}');
INSERT INTO public.simulation_task (id, scenario_version_id, "position", title, workplace_context, instructions, required, translations) VALUES (10, 4, 2, 'Partnering with AI to research, design and create', 'Turn AI insights into polished and visual presentations under pressure.', '<ul><li>Create a&nbsp;3-slide PowerPoint presentation&nbsp;for an upcoming council forum. You’ll need to use AI to assist with each part of the task</li></ul>', true, '{}');
INSERT INTO public.simulation_task (id, scenario_version_id, "position", title, workplace_context, instructions, required, translations) VALUES (11, 4, 3, 'Click, prompt, fix: Your first steps into AI-powered debugging', 'Use AI to troubleshoot broken code even if you''re not a developer.', '<p>An unexpected error has occurred on a client’s website. Your manager has asked you to investigate it as a top priority. You’re not a developer so you will need to partner with AI to get to the bottom of the issue!</p>', true, '{}');
INSERT INTO public.simulation_task (id, scenario_version_id, "position", title, workplace_context, instructions, required, translations) VALUES (12, 5, 1, 'New Presales Opportunity', 'Start researching potential solutions for a new presales opportunity', '<ul><li>Create a list of questions for the customer based on your research</li><li>Use the customer feedback from these questions to begin formulating a solution architecture for ABC Financial Services</li></ul>', true, '{}');
INSERT INTO public.simulation_task (id, scenario_version_id, "position", title, workplace_context, instructions, required, translations) VALUES (13, 5, 2, 'Prepare for Initial Customer Meeting', 'Based on feedback from the customer and the sales team, prepare for your first discussion with the customer', '<ul><li>Review the customer''s requirements and internal meeting notes</li><li>Create a video presentation focusing on why HPE is the right choice, the benefits of HPE GreenLake, and potential HPE solutions</li></ul>', true, '{}');
INSERT INTO public.simulation_task (id, scenario_version_id, "position", title, workplace_context, instructions, required, translations) VALUES (14, 5, 3, 'Solution Options Assessment', 'Prepare for internal sales team meeting to review solution options and discuss which product(s) should be proposed', '<ul><li>Research and gather relevant information to assess potential solutions effectively</li><li>Submit the completed pros and cons analysis spreadsheet with concise points for each solution option</li></ul>', true, '{}');
INSERT INTO public.simulation_task (id, scenario_version_id, "position", title, workplace_context, instructions, required, translations) VALUES (15, 5, 4, 'Customer Proposal', 'Based on your work and additional input from the sales team, put together a presentation outlining the proposed solution', '<ul><li>Utilize the provided resources to craft a persuasive sales presentation focused on key points and illustrating the solution&nbsp;</li></ul>', true, '{}');
INSERT INTO public.simulation_task (id, scenario_version_id, "position", title, workplace_context, instructions, required, translations) VALUES (16, 6, 1, 'Welcome to HPE', 'Get familiar with HPE as a company', '<ul><li>Review HPE Sales Professional documentation and HPE website</li><li>Create a high-level presentation on HPE</li></ul>', true, '{}');
INSERT INTO public.simulation_task (id, scenario_version_id, "position", title, workplace_context, instructions, required, translations) VALUES (17, 6, 2, 'Introduce Your Customer to HPE', 'Kick off an HPE customer presentation', '<ul><li>Research presentation advice</li><li>Prepare talking points based on your slides</li><li>Record a video of yourself presenting slides from Task 1</li></ul>', true, '{}');
INSERT INTO public.simulation_task (id, scenario_version_id, "position", title, workplace_context, instructions, required, translations) VALUES (18, 6, 3, 'Conduct Customer Research', 'Understand your target customer and get your manager up to speed', '<ul><li>Conduct research on target customer</li><li>Create a presentation to share with your manager</li></ul>', true, '{}');
INSERT INTO public.simulation_task (id, scenario_version_id, "position", title, workplace_context, instructions, required, translations) VALUES (20, 7, 1, 'AI-Powered Debugging and Refactoring', 'Learn what process automation is in order to meet your client''s needs', '$65', true, '{}');
INSERT INTO public.simulation_task (id, scenario_version_id, "position", title, workplace_context, instructions, required, translations) VALUES (21, 7, 2, 'Create a process flow', 'Design a process flow for a key persona in the process automation design', '<p><span style="color:#000000;">The participant will be given a high-level feature request. They will use an agentic AI development environment to generate a complete specification for this feature. They will then actively review and edit the specification to add new requirements and adjust the design. Finally, they will instruct the AI to implement the feature based on the approved specification.</span></p><p><br>&nbsp;</p>', true, '{}');
INSERT INTO public.simulation_task (id, scenario_version_id, "position", title, workplace_context, instructions, required, translations) VALUES (22, 7, 3, 'Building from Scratch with Spec-Driven Development', '', '<ul><li><span style="color:#1b1c1d;">You will be provided with a description of a manual business process. They will analyse this process and design an agentic AI system to automate it. They will not write code; instead, they will prepare a three-slide presentation to pitch their proposed solution to management.</span></li><li><span style="color:#000000;">Deliverable: </span><span style="color:#1b1c1d;">A 3-slide presentation file (e.g., PowerPoint or Google Slides) that outlines the analysis of the current process, the design of the proposed agentic AI solution, and the expected business impact</span></li></ul><p><br>&nbsp;</p>', true, '{}');
INSERT INTO public.simulation_task (id, scenario_version_id, "position", title, workplace_context, instructions, required, translations) VALUES (23, 8, 1, 'Introduction to Cyber Security', '', '<p><span style="color:#000000;">Investigate a simulated cyber-attack scenario involving a mid-sized company that has suffered a data breach. Analyse the attack vector, the type of data compromised, and the operational impact. Produce a comprehensive report that:</span></p><ol><li><span style="color:#000000;">Summarizes the findings of your investigation, including the nature and extent of the breach</span></li><li><span style="color:#000000;">Identifies what vulnerabilities were exploited</span></li><li><span style="color:#000000;">Describes potential ramifications for the business (legal, financial, reputational)</span></li><li><span style="color:#000000;">Outlines key recommendations to improve the client’s cybersecurity posture</span></li></ol>', true, '{}');
INSERT INTO public.simulation_task (id, scenario_version_id, "position", title, workplace_context, instructions, required, translations) VALUES (24, 8, 2, 'Cybersecurity risk assessment', 'Conduct a comprehensive risk assessment', '<ul><li>Analyse an organisation and their assets to create a detailed outline of the potential threats and risks.</li></ul>', true, '{}');
INSERT INTO public.simulation_task (id, scenario_version_id, "position", title, workplace_context, instructions, required, translations) VALUES (25, 9, 1, 'Software review', 'Review a web application and plan for future improvements', '<ul><li>Review customer feedback and create a summarised list of bugs and new features for a client''s site</li></ul>', true, '{}');
INSERT INTO public.simulation_task (id, scenario_version_id, "position", title, workplace_context, instructions, required, translations) VALUES (26, 9, 2, 'Identifying root causes and fixing bugs', 'Identify the root cause of bugs and implementing a fix to improve the application', '<ul><li>Access code, identify the root cause of a bug, and implement a fix by updating the code</li></ul>', true, '{}');
INSERT INTO public.simulation_task (id, scenario_version_id, "position", title, workplace_context, instructions, required, translations) VALUES (27, 10, 1, 'Create a Proposal for a RESTful Web Service', 'Explore how to use Java Spring Boot and the GreenLake cloud platform to design a RESTful web service', '<ul><li>Meet your supervisor Stella Yun, a senior software Engineering Director at Hewlett Packard Enterprise</li><li>Explore the technical documentation for Java Spring Boot and GreenLake Cloud Platform</li><li>Write a proposal for a RESTful web service to manage a list of employees</li></ul>', true, '{}');
INSERT INTO public.simulation_task (id, scenario_version_id, "position", title, workplace_context, instructions, required, translations) VALUES (28, 10, 2, 'Build a Basic RESTful Web Service', 'Using Java Spring Boot, build a basic RESTful Web Service that can send basic server requests', '<ul><li>Build a basic web server application in Java Spring Boot that can accept and respond to HTTP requests</li></ul>', true, '{}');
INSERT INTO public.simulation_task (id, scenario_version_id, "position", title, workplace_context, instructions, required, translations) VALUES (29, 10, 3, 'Implement the Ability to Upload Data', 'Add application support for uploading JSON data', '<ul><li>Build out your application so that it supports uploading JSON data</li></ul>', true, '{}');
INSERT INTO public.simulation_task (id, scenario_version_id, "position", title, workplace_context, instructions, required, translations) VALUES (30, 10, 4, 'Create Unit Tests', 'Develop a set of unit tests to assess your application’s performance', '<ul><li>Develop and run a set of unit tests to assess your application’s performance</li></ul>', true, '{}');
