-- Approved local academic catalogue snapshot for UC-04/UC-05.
-- Contains only public scenario learning content and server-side locked definitions.
-- Deliberately excludes users, representatives, credentials, tokens, enrollments,
-- submissions, completions, uploaded file bytes, private evidence and provider data.
DO $$
DECLARE
    approved_slugs text[] := ARRAY[
        'hpe-software-engineering',
        'datacom-service-desk',
        'datacom-introduction-to-cloud',
        'datacom-partnering-with-ai',
        'hpe-presales',
        'hpe-digital-sales',
        'datacom-automation-ai-accelerator',
        'datacom-cyber-security-operations',
        'datacom-software-development'
    ];
    approved_count integer;
    total_count integer;
BEGIN
    SELECT count(*) INTO approved_count FROM public.scenario WHERE slug = ANY(approved_slugs);
    SELECT count(*) INTO total_count FROM public.scenario;

    IF approved_count = 9 AND total_count = 9 THEN
        IF EXISTS (
            SELECT 1
            FROM public.scenario s
            LEFT JOIN public.scenario_version v ON v.id = s.current_version_id AND v.scenario_id = s.id
            WHERE s.slug = ANY(approved_slugs)
              AND (s.availability_status <> 'AVAILABLE' OR s.industry_code <> 'IT'
                   OR v.id IS NULL OR v.status <> 'PUBLISHED')
        ) THEN
            RAISE EXCEPTION 'V32_APPROVED_CATALOGUE_STATE_MISMATCH';
        END IF;
        RETURN;
    END IF;

    IF total_count <> 0 OR approved_count <> 0 THEN
        RAISE EXCEPTION 'V32_PARTIAL_OR_CONFLICTING_CATALOGUE: total %, approved %', total_count, approved_count;
    END IF;
    IF EXISTS (SELECT 1 FROM public.enterprise) OR EXISTS (SELECT 1 FROM public.career_skill) THEN
        RAISE EXCEPTION 'V32_REFERENCE_DATA_CONFLICT: enterprise and career_skill must be empty when seeding';
    END IF;

    -- Child rows are an approved immutable snapshot of already-published versions.
    -- Disable only the publication immutability guard for the duration of this transaction.
    ALTER TABLE public.simulation_task DISABLE TRIGGER guard_content;
    ALTER TABLE public.task_deliverable_definition DISABLE TRIGGER guard_content;
    ALTER TABLE public.task_skill DISABLE TRIGGER guard_content;
    ALTER TABLE public.scenario_learning_policy DISABLE TRIGGER guard_learning_content;
    ALTER TABLE public.task_learning_policy DISABLE TRIGGER guard_learning_content;

